// Define job search parameters
const jobSearchConfig = {
  keywords: ['AI Adoption Specialist', 'Legal Technology', 'Instructional Design'],
  locations: ['Remote', 'Texas', 'Dallas'],
  jobBoards: [
    {
      name: 'Indeed',
      url: 'https://www.indeed.com/jobs',
      strategy: 'indeed'
    },
    {
      name: 'LinkedIn',
      url: 'https://www.linkedin.com/jobs',
      strategy: 'linkedin'
    },
    {
      name: 'SimplyHired',
      url: 'https://www.simplyhired.com/search',
      strategy: 'job_listing'
    }
  ]
};

// Generate search URLs
const searchUrls = [];
for (const board of jobSearchConfig.jobBoards) {
  for (const keyword of jobSearchConfig.keywords) {
    for (const location of jobSearchConfig.locations) {
      searchUrls.push({
        board: board.name,
        keyword: keyword,
        location: location,
        url: `${board.url}?q=${encodeURIComponent(keyword)}&l=${encodeURIComponent(location)}`,
        strategy: board.strategy
      });
    }
  }
}

return searchUrls;

