cd /path/to/jobsearch && source venv/bin/activate && python -c "
import asyncio
import json
import sys
from crawl4ai import AsyncWebCrawler
from crawl4ai.extraction_strategy import JsonCssExtractionStrategy

url = '{{$json.url}}'
strategy = '{{$json.strategy}}'

# Define extraction strategies
strategies = {
    'indeed': {
        'baseSelector': '.jobsearch-ResultsList .result',
        'fields': [
            {'name': 'title', 'selector': '.jobTitle span[title]', 'type': 'text'},
            {'name': 'company', 'selector': '.companyName', 'type': 'text'},
            {'name': 'location', 'selector': '.locationsContainer', 'type': 'text'},
            {'name': 'salary', 'selector': '.salary-snippet', 'type': 'text'}
        ]
    },
    'linkedin': {
        'baseSelector': '.jobs-search__results-list li',
        'fields': [
            {'name': 'title', 'selector': '.base-search-card__title', 'type': 'text'},
            {'name': 'company', 'selector': '.base-search-card__subtitle', 'type': 'text'},
            {'name': 'location', 'selector': '.job-search-card__location', 'type': 'text'}
        ]
    },
    'job_listing': {
        'baseSelector': '[data-testid=\'job-card\'], .job-listing',
        'fields': [
            {'name': 'title', 'selector': '.job-title, h2, h3', 'type': 'text'},
            {'name': 'company', 'selector': '.company-name', 'type': 'text'},
            {'name': 'location', 'selector': '.location', 'type': 'text'}
        ]
    }
}

async def scrape():
    async with AsyncWebCrawler(headless=True) as crawler:
        strategy_config = strategies.get(strategy, strategies['job_listing'])
        extraction = JsonCssExtractionStrategy(schema={'name': 'Jobs', **strategy_config})
        result = await crawler.arun(url=url, extraction_strategy=extraction)
        return result

result = asyncio.run(scrape())
print(json.dumps({'success': result.success, 'data': result.extracted_content}))
"

