// Score job relevance based on Eric's profile
const ericProfile = {
  skills: ['AI Adoption', 'Legal Technology', 'Instructional Design', 'ChatGPT', 'Claude', 'iManage', 'NetDocuments'],
  experience: 12,
  desiredSalary: 100000,
  preferredLocation: ['Remote', 'Texas']
};

function scoreJob(job) {
  let score = 0;
  const title = (job.title || '').toLowerCase();
  const description = (job.description || '').toLowerCase();
  const combined = title + ' ' + description;

  // Skill matching (40 points max)
  for (const skill of ericProfile.skills) {
    if (combined.includes(skill.toLowerCase())) {
      score += 5;
    }
  }

  // Title relevance (30 points max)
  const titleKeywords = ['ai', 'adoption', 'specialist', 'legal', 'technology', 'instructional'];
  for (const keyword of titleKeywords) {
    if (title.includes(keyword)) {
      score += 5;
    }
  }

  // Location preference (20 points)
  const location = (job.location || '').toLowerCase();
  if (location.includes('remote')) score += 20;
  else if (location.includes('texas') || location.includes('dallas')) score += 15;

  // Salary match (10 points)
  const salary = job.salary || '';
  if (salary.includes('100') || salary.includes('110') || salary.includes('120')) {
    score += 10;
  }

  return {
    ...job,
    matchScore: score,
    recommendation: score >= 60 ? 'Apply Now' : score >= 40 ? 'Consider' : 'Skip',
    scoreBreakdown: {
      skills: Math.min(40, score),
      title: Math.min(30, score - 40),
      location: location.includes('remote') ? 20 : 0,
      salary: salary ? 10 : 0
    }
  };
}

// Parse scraped data
let jobs = [];
try {
  const data = JSON.parse($input.item.json.data || '[]');
  jobs = Array.isArray(data) ? data : [data];
} catch (e) {
  jobs = [{title: 'Error parsing', error: e.toString()}];
}

// Score all jobs
const scoredJobs = jobs.map(scoreJob);

// Sort by score
scoredJobs.sort((a, b) => b.matchScore - a.matchScore);

return scoredJobs;

